fn ascii_lower(c: char) -> char {
    // Only ASCII 'A'..'Z' are lowercased; everything else unchanged.
    if ('A'..='Z').contains(&c) {
        // Safe because 'A'..'Z' are single-byte ASCII.
        let b = c as u8;
        (b + (b'a' - b'A')) as char
    } else {
        c
    }
}

fn is_palindrome(text: Vec<char>) -> (bool) {
    let n = text.len();
    let mut i: usize = 0;
    let mut j: usize = n; // exclusive upper bound

    while i < j {
        j -= 1; // now j is the mirrored index from the end
        if ascii_lower(text[i]) != ascii_lower(text[j]) {
            return (false);
        }
        i += 1;
    }
    (true)
}